import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import { getComments, getPost, getPosts } from '@/lib/posts'

export const dynamicParams = true

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

async function getPostData(id: string) {
  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  if (!post.id) {
    notFound()
  }

  return { post, comments }
}

export async function generateMetadata(
  props: PageProps<'/blog/[id]'>,
): Promise<Metadata> {
  const { id } = await props.params

  try {
    const post = await getPost(id)

    if (!post.id) {
      return { title: 'Post Not Found' }
    }

    const description = post.body.substring(0, 160)

    return {
      title: post.title,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return { title: 'Post Not Found' }
  }
}

export default async function BlogPostPage(
  props: PageProps<'/blog/[id]'>,
) {
  const { id } = await props.params
  let data: Awaited<ReturnType<typeof getPostData>>

  try {
    data = await getPostData(id)
  } catch (error) {
    if (error && typeof error === 'object' && 'digest' in error) {
      throw error
    }

    throw new Error(`Unable to load blog post ${id}`, { cause: error })
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

